window.VO = [{"id":"n01","text":"You're the only witness. Again.","at":0.24,"t0":0.12,"t1":1.965},{"id":"n02","text":"Watch his face.","at":4.33,"t0":2.165,"t1":3.215},{"id":"n03","text":"This time, he's one of these six, and whoever you pick goes to prison.","at":9.87,"t0":4.935,"t1":8.74},{"id":"n04","text":"Out of ten, how sure are you?","at":20.38,"t0":10.19,"t1":11.74},{"id":"o01","text":"So? Which one?","at":25.68,"t0":12.84,"t1":13.92},{"id":"o02","text":"Good. That's him.","at":30.44,"t0":15.22,"t1":16.4},{"id":"n05","text":"He's a drawing, so he can't see what you picked.","at":34.1,"t0":17.05,"t1":19.44},{"id":"n06","text":"So here's the answer.","at":39.48,"t0":19.74,"t1":20.995},{"id":"n07","text":"It's number three.","at":42.23,"t0":21.115,"t1":22.17},{"id":"n08","text":"Look at him.","at":45.24,"t0":22.62,"t1":23.42},{"id":"n09","text":"Now how sure are you that it's him?","at":47.24,"t0":23.62,"t1":25.125},{"id":"n10","text":"It isn't number three.","at":51.85,"t0":25.925,"t1":27.16},{"id":"n11","text":"I made that up.","at":54.82,"t0":27.41,"t1":28.435},{"id":"n11b","text":"But he looked right, didn't he?","at":57.47,"t0":28.735,"t1":30.145},{"id":"n12","text":"And whoever you picked is still going to prison.","at":61.09,"t0":30.545,"t1":32.835},{"id":"n14","text":"If I hadn't asked you first, one good, and you'd swear you were this sure from the start.","at":67.27,"t0":33.635,"t1":38.085},{"id":"n15","text":"In America, police told a real witness she'd picked the same man again.","at":76.97,"t0":38.485,"t1":42.565},{"id":"n15b","text":"In her own words, Bingo. I did it right.","at":85.43,"t0":42.715,"t1":45.085},{"id":"n16","text":"Ronald Cotton lost more than ten years.","at":90.97,"t0":45.485,"t1":47.89},{"id":"n18","text":"I could tell you which one, but you'd believe me.","at":98.08,"t0":49.04,"t1":51.355},{"id":"o03","text":"So? Which one?","at":103.41,"t0":51.705,"t1":52.785},{"id":"o04","text":"Good. That's him.","at":108.57,"t0":54.285,"t1":55.465}];
